function advance(text,topic,score){game.turns++;game.eventTurns=game.event?game.eventTurns+1:0;game.topicSet.add(topic);game.lastTopics.push(topic);if(game.lastTopics.length>4)game.lastTopics.shift();if(/\?/.test(text))game.curiosity+=.7;if(topic==='values'||topic==='feelings'||topic==='family'||topic==='relationship')game.depth+=1.2;if(topic==='flirt')game.joy+=score>0?.9:.2;if(topic!=='general')game.curiosity+=.25;game.comfort+=score>0?.85:score<0?-.75:.34;game.respect+=score>=0?.25:-.8;game.openness+=(topic==='values'||topic==='feelings'||topic==='family')?.65:.12;if(text.length>90)game.openness+=.15;extractFact(text);detectName(text);
  if(game.respect< -1.5){game.comfort=Math.max(0,game.comfort);game.openness=Math.max(0,game.openness)}
  // Progression is inferred from rapport, conversational breadth and mutual disclosure—not a message counter.
  if(game.stage===1&&game.comfort>=2.1&&game.topicSet.size>=2)game.stage=2;
  if(game.stage===2&&game.comfort>=3.8&&game.depth>=1.2&&game.topicSet.size>=3)game.stage=3;
  if(game.stage===3&&game.turns>=6&&game.comfort>=4.8&&game.depth>=2.2&&game.topicSet.size>=3){game.stage=4;return true}
  if(game.stage===4&&game.event&&game.eventTurns>=3&&game.depth>=2.2)game.stage=5;
  return false}
function triggerEvent(){if(game.event)return;game.event=true;game.eventTurns=0;document.querySelector('.scene').classList.add('event-night');showToast('For a moment, the whole room holds its breath.');setTimeout(()=>{addMessage('her','Oh—there go the lights.');setTimeout(()=>{addMessage('her','Well, this is either very atmospheric or a test of how well I can recognize you by candlelight. Are you okay?');updateFace();ui.input.focus()},650)},500)}
function updateFace(){const light=game.joy+game.comfort*.18-game.respect*.12;ui.mood.textContent=game.respect< -1?'a little guarded':light>5?'at ease, and quietly delighted':light>2?'more relaxed now':game.turns>1?'curious about you':'a little nervous, in a good way';ui.mouth.setAttribute('d',light>3?'M192 303 Q213 324 235 303':'M195 306 Q213 317 231 306');ui.character.classList.toggle('laughing',game.joy>2&&game.turns%3===0)}
function userSend(text){text=text.trim();if(!text||game.ended||!game.started)return;ui.input.value='';ui.input.style.height='auto';ui.send.disabled=true;const topic=topicOf(text),score=sentiment(text);addMessage('you',text);const eventNow=advance(text,topic,score);const answer=responseFor(text,topic);say(answer,680+Math.min(text.length*5,620));if(eventNow){setTimeout(triggerEvent,1600)}else if(game.turns===2&&game.topicSet.size<2){setTimeout(()=>{if(!game.ended)addMessage('her','Can I ask you something? What’s a little thing you’re looking forward to lately?')},1850)}else if(game.turns>4&&game.turns%4===0&&!/\?/.test(text)){setTimeout(()=>{if(!game.ended)addMessage('her','I’m realizing I’ve been doing most of the asking. What are you curious about?')},1700)}if(game.event&&game.stage===4){setTimeout(()=>{game.stage=5},2400)}updateClock()}
function setClock(){const base=new Date();base.setHours(19,42,0,0);const elapsed=game.started?(Date.now()-game.runStarted)/60000:0;const mins=42+Math.floor(elapsed*1.5);base.setMinutes(mins);ui.clock.textContent=base.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});const label=base.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});document.querySelector('.ambient').textContent=`The Juniper Room · ${label}`}
function updateClock(){setClock()}
setInterval(setClock,15000);
function closingText(){let title,text,summary;if(game.respect< -1){title='A quieter goodbye';text='Some evenings don’t quite find their rhythm, and that’s okay. Mara gives you a kind, honest smile as the check arrives.';summary='“Thanks for meeting me. I’m glad we got to talk.”'}else if(game.comfort+game.joy+game.depth>12){title='The evening lingers';text='The restaurant has gone soft around the edges. Mara looks at you for a moment, then smiles like she’s deciding whether to say the thing out loud.';summary=game.facts.length?`“I’m going to remember this—and what you told me about ${game.facts[0].replace(/^I am /i,'you being ').replace(/^I /i,'you ')}.”`:'“I had a really good time. I didn’t expect the evening to feel this easy.”'}else if(game.depth>2||game.comfort>4){title='A warm kind of maybe';text='Mara lingers over the last sip of her drink, thoughtful but smiling. It wasn’t a perfect movie moment—it felt more like a beginning.';summary='“I’m glad we did this. I’d like to see where another conversation goes.”'}else{title='A lovely first chapter';text='There’s still a little first-date awkwardness between you, but Mara’s smile is genuine as the evening winds down.';summary='“Thanks for a really nice evening. I’m glad we finally met.”'}return{title,text,summary}}
function openEnding(){const c=closingText();$('#modal-eyebrow').textContent=game.event?'Outside, the night is waiting':'The check is here';$('#modal-title').textContent=c.title;$('#modal-text').textContent=c.text;$('#summary').textContent=c.summary;$('#keepGoing').textContent='Stay a little longer';$('#finish').textContent='End the evening';ui.modal.classList.add('open');game.finalAsked=true}
function closeEnding(){ui.modal.classList.remove('open');game.ended=false;game.finalAsked=false;addMessage('her',game.comfort+game.joy>8?'I’m glad we’re not rushing off just yet.':'One more minute, then. I like how the room sounds when it’s winding down.');ui.input.focus()}
function finish(){const c=closingText();game.ended=true;ui.modal.classList.remove('open');addMessage('her',c.summary);ui.prompts.innerHTML='';ui.input.disabled=true;ui.input.placeholder='The evening has come to a close.';$('#endDate').textContent='Start a new evening';$('#endDate').onclick=resetGame;$('#restart').textContent='New evening';}
function resetGame(){game=freshState();ui.messages.innerHTML='';ui.prompts.innerHTML='<button class="prompt-chip">Ask what she ordered</button><button class="prompt-chip">Tell her what you noticed</button><button class="prompt-chip">Ask about her week</button>';ui.input.disabled=false;ui.input.placeholder='Say what you’d really say…';$('#endDate').textContent='Ask for the check';$('#endDate').onclick=openEnding;$('#restart').textContent='New evening';document.querySelector('.scene').classList.remove('event-night');ui.modal.classList.remove('open');ui.start.classList.remove('gone');ui.clock.textContent='7:42 PM';document.querySelector('.ambient').textContent='The Juniper Room · 7:42 PM'}
ui.form.addEventListener('submit',e=>{e.preventDefault();userSend(ui.input.value)});
ui.input.addEventListener('input',()=>{ui.input.style.height='auto';ui.input.style.height=Math.min(ui.input.scrollHeight,120)+'px'});
ui.input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ui.form.requestSubmit()}});
ui.prompts.addEventListener('click',e=>{const b=e.target.closest('.prompt-chip');if(!b)return;userSend(b.textContent)});
$('#begin').addEventListener('click',begin);$('#endDate').addEventListener('click',openEnding);$('#keepGoing').addEventListener('click',closeEnding);$('#finish').addEventListener('click',finish);$('#restart').addEventListener('click',resetGame);
$('#about').addEventListener('click',()=>{showToast('A small, locally-powered story. Your words stay in this browser.')});
$('#sound').addEventListener('click',()=>{try{if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(ambience){ambience.forEach(o=>{try{o.stop()}catch(_){}});ambience=null;$('#sound').textContent='♫';$('#sound').title='Turn on soft room tone';showToast('Room tone off');return}const master=audioCtx.createGain();master.gain.value=.012;master.connect(audioCtx.destination);const a=audioCtx.createOscillator(),b=audioCtx.createOscillator(),filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=240;a.type='triangle';b.type='sine';a.frequency.value=78;b.frequency.value=116;a.connect(filter);b.connect(filter);filter.connect(master);a.start();b.start();ambience=[a,b];$('#sound').textContent='♫̸';$('#sound').title='Turn off soft room tone';showToast('A little room tone, just for atmosphere')}catch(e){showToast('Audio is not available in this browser')}});
</script>
</body>
</html>

